[ExtensionOf(formStr(PurchCopying))]
final class METPurchCopying_Form_Extension
{

}

Method.Source:
/// <summary>
/// Can of Purch copying form
/// </summary>
/// <returns>true or false</returns>
boolean canClose()
{
    boolean ret;

    if (copyPrecisely.value())
    {
        TmpFrmVirtual tmpFrmVirtual = tmpFrmVirtualHeader;

        select firstonly tmpFrmVirtual order by Recid desc;

        if (tmpFrmVirtual)
        {
            purchCopyingForm.parmRecordNum(tmpFrmVirtual.RecordNo);
            purchCopyingForm.parmTableNum(tmpFrmVirtual.TableNum);
        }
    }

    ret = next canClose();

    return ret;

}
